<?php
declare(strict_types=1);requireRole('subject-officer');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='distribute-items';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();
if($_SERVER['REQUEST_METHOD']==='POST'){$camp=filter_input(INPUT_POST,'camp_id',FILTER_VALIDATE_INT);$beneficiary=filter_input(INPUT_POST,'beneficiary_id',FILTER_VALIDATE_INT);$item=filter_input(INPUT_POST,'item_id',FILTER_VALIDATE_INT);$officer=filter_input(INPUT_POST,'officer_id',FILTER_VALIDATE_INT);$quantity=filter_input(INPUT_POST,'quantity',FILTER_VALIDATE_INT);if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$camp||!$beneficiary||!$item||!$officer||!$quantity||$quantity<1)$errors[]='Complete all handover details.';if(!$errors){try{$db->beginTransaction();$check=$db->prepare("SELECT vc.ds_division_id,vc.attended_count,vc.handed_over_count FROM vision_camps vc JOIN beneficiaries b ON b.id=:beneficiary AND b.ds_division_id=vc.ds_division_id AND b.status='active' JOIN users u ON u.id=:officer AND u.ds_division_id=vc.ds_division_id AND u.role='social-service-officer' AND u.status='active' JOIN inventory_items i ON i.id=:item JOIN item_categories c ON c.id=i.category_id AND c.distribution_type='direct' WHERE vc.id=:camp AND vc.requested_by=:user AND vc.stage='distribution-in-progress' FOR UPDATE");$check->execute(['beneficiary'=>$beneficiary,'officer'=>$officer,'item'=>$item,'camp'=>$camp,'user'=>$_SESSION['user_id']]);$data=$check->fetch();if(!$data)throw new RuntimeException('Camp, beneficiary, item, or assigned officer is not valid for this handover.');if($data['attended_count']!==null&&(int)$data['handed_over_count']+$quantity>(int)$data['attended_count'])throw new RuntimeException('Handover quantity exceeds recorded attendance.');$stmt=$db->prepare('INSERT INTO vision_camp_handovers(camp_id,beneficiary_id,item_id,quantity,officer_id,handed_by) VALUES(:camp,:beneficiary,:item,:quantity,:officer,:user)');$stmt->execute(['camp'=>$camp,'beneficiary'=>$beneficiary,'item'=>$item,'quantity'=>$quantity,'officer'=>$officer,'user'=>$_SESSION['user_id']]);$id=(int)$db->lastInsertId();$db->prepare('UPDATE vision_camps SET handed_over_count=handed_over_count+:quantity WHERE id=:camp')->execute(['quantity'=>$quantity,'camp'=>$camp]);$db->commit();logActivity('Vision Handover','Assigned camp item to Social Service Officer','HO-'.str_pad((string)$id,4,'0',STR_PAD_LEFT),'pending');$_SESSION['flash_success']='Vision camp item handed over for beneficiary distribution.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=distribute-items');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to create handover.';}}}
try{$camps=$db->prepare("SELECT id,ds_division_id FROM vision_camps WHERE requested_by=:user AND stage='distribution-in-progress' ORDER BY id DESC");$camps->execute(['user'=>$_SESSION['user_id']]);$camps=$camps->fetchAll();$beneficiaries=$db->query("SELECT id,full_name,nic,ds_division_id FROM beneficiaries WHERE status='active' ORDER BY full_name")->fetchAll();$items=$db->query("SELECT i.id,i.item_name,i.variety FROM inventory_items i JOIN item_categories c ON c.id=i.category_id WHERE c.distribution_type='direct' AND c.status='active' ORDER BY i.item_name")->fetchAll();$officers=$db->query("SELECT id,full_name,ds_division_id FROM users WHERE role='social-service-officer' AND status='active' AND ds_division_id IS NOT NULL ORDER BY full_name")->fetchAll();$rows=$db->prepare('SELECT h.*,b.full_name,i.item_name,i.variety,u.full_name officer_name FROM vision_camp_handovers h JOIN beneficiaries b ON b.id=h.beneficiary_id JOIN inventory_items i ON i.id=h.item_id JOIN users u ON u.id=h.officer_id WHERE h.handed_by=:user ORDER BY h.id DESC');$rows->execute(['user'=>$_SESSION['user_id']]);$rows=$rows->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$camps=$beneficiaries=$items=$officers=$rows=[];$errors[]='Vision handovers are unavailable.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vision Camp Handovers | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/subject-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Distribute Items</h1></div></header><main class="dashboard-content admin-operation-page"><?php if($success):?><div class="alert alert-success"><?=$success?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="admin-data-card"><div class="admin-data-header"><h2>Vision Camp Beneficiary Handover</h2></div><form method="post" class="master-inline-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><label>Active Camp<select name="camp_id" required><option value="">Select camp</option><?php foreach($camps as $r):?><option value="<?=(int)$r['id']?>">VC-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></option><?php endforeach;?></select></label><label>Beneficiary<select name="beneficiary_id" required><option value="">Select beneficiary</option><?php foreach($beneficiaries as $r):?><option value="<?=(int)$r['id']?>"><?=htmlspecialchars($r['full_name'].' — '.$r['nic'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Direct Item<select name="item_id" required><option value="">Select item</option><?php foreach($items as $r):?><option value="<?=(int)$r['id']?>"><?=htmlspecialchars($r['item_name'].($r['variety']?' — '.$r['variety']:''),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Social Service Officer<select name="officer_id" required><option value="">Select officer</option><?php foreach($officers as $r):?><option value="<?=(int)$r['id']?>"><?=htmlspecialchars($r['full_name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="quantity" value="1" min="1" required></label><button class="admin-primary-action">Hand Over</button></form></section><section class="admin-data-card operation-list-card"><div class="admin-data-header"><h2>Camp Handovers</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table"><thead><tr><th>ID</th><th>Camp</th><th>Beneficiary</th><th>Item</th><th>Qty</th><th>Officer</th><th>Status</th><th>Date</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="admin-empty-row">No camp handovers available.</td></tr><?php else:foreach($rows as $r):?><tr><td>HO-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td>VC-<?=str_pad((string)$r['camp_id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['item_name'],ENT_QUOTES,'UTF-8')?></td><td><?=(int)$r['quantity']?></td><td><?=htmlspecialchars($r['officer_name'],ENT_QUOTES,'UTF-8')?></td><td><?=ucfirst($r['status'])?></td><td><?=date('d M Y',strtotime($r['handed_at']))?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
